--
-- Table structure for table `T_CK_COMPONENT_GUIDE`
--

DROP TABLE IF EXISTS `T_CK_COMPONENT_GUIDE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_COMPONENT_GUIDE` (
  `CMGU_ID` varchar(35) NOT NULL COMMENT 'COMPONENT GUIDE  - UUID',
  `CMGU_APPS_CODE` varchar(35) NOT NULL COMMENT 'COMPONENT GUIDE APPS CODE - REFERENCE T_CORE_APPS:APPS_CODE',
  `CMGU_SERVICE_TYPE` varchar(35) DEFAULT NULL COMMENT 'COMPONENT GUIDE SERVICE - REFERENCE T_CK_MST_SERVICE_TYPE:SSST_ID',
  `CMGU_COMPONENT_ID` varchar(1024) NOT NULL COMMENT 'COMPONENT GUIDE COMPONENT ID - clicdo.claim.doi.list.table_jobs : clicdo.claim.doi.list.page',
  `CMGU_GUIDE` mediumtext COMMENT 'COMPONENT GUIDE DESCRIPTION',
  `CMGU_GUIDE_OTH` mediumtext COMMENT 'COMPONENT GUIDE DESCRIPTION OTHER LANGUAGE',
  `CMGU_STATUS` char(1) DEFAULT NULL COMMENT 'COMPONENT GUIDE STATUS',
  `CMGU_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CMGU_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CMGU_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CMGU_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CMGU_ID`),
  KEY `ID_CK_CMP_GUIDE_COMPONET_ID` (`CMGU_COMPONENT_ID`),
  KEY `FK_CK_CMP_GUIDE_CORE_APPS` (`CMGU_APPS_CODE`),
  KEY `FK_CK_CMP_GUIDE_CK_MST_SERVICE_TYPE` (`CMGU_SERVICE_TYPE`),
  CONSTRAINT `FK_CK_CMP_GUIDE_CK_MST_SERVICE_TYPE` FOREIGN KEY (`CMGU_SERVICE_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_CMP_GUIDE_CORE_APPS` FOREIGN KEY (`CMGU_APPS_CODE`) REFERENCES `T_CORE_APPS` (`APPS_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='COMPONENT GUIDE TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

