--
-- Table structure for table `T_CK_DO_INVOICE`
--

DROP TABLE IF EXISTS `T_CK_DO_INVOICE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_DO_INVOICE` (
  `INV_ID` varchar(35) NOT NULL COMMENT 'INVOICE ID - UUID',
  `INV_DO_ID` varchar(35) NOT NULL COMMENT 'DO RELATED TO THE INVOICE - REFERECNES T_CK_DO:DO_ID',
  `INV_NO` varchar(255) NOT NULL COMMENT 'INVOICE NUMBER - IMF2001535',
  `INV_TAX_NO` varchar(255) DEFAULT NULL COMMENT 'TAX INVOICE NUMBER FAKTUR PAJAK- 010.003-22 103351310',
  `INV_TYPE` varchar(35) NOT NULL COMMENT 'INVOICE TYPE - REFERECNES T_CK_MST_INVOICE_TYPE:INVT_ID',
  `INV_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'INVOICE AMOUNT BEFORE TAX - 12,0000',
  `INV_TAX` decimal(15,2) DEFAULT '0.00' COMMENT 'INVOICE TAX AMOUNT - 12,0000',
  `INV_CCY` varchar(3) DEFAULT NULL COMMENT 'INVOICE CURRENCY  - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `INV_DOC` varchar(1024) DEFAULT NULL COMMENT 'INVOICE INVOICE PATH REFERENCE FROM SYS_PARAM SETUP',
  `INV_STATUS` char(1) DEFAULT NULL COMMENT 'INVOICE TYPE STATUS',
  `INV_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `INV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `INV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `INV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`INV_ID`),
  KEY `FK_CK_DOI_INVOICE_CK_DO` (`INV_DO_ID`),
  KEY `FK_CK_DOI_INVOICE_CK_MST_INVOICE_TYPE` (`INV_TYPE`),
  KEY `FK_CK_DOI_INVOICE_MST_CCY` (`INV_CCY`),
  CONSTRAINT `FK_CK_DOI_INVOICE_CK_DO` FOREIGN KEY (`INV_DO_ID`) REFERENCES `T_CK_DO` (`DO_ID`),
  CONSTRAINT `FK_CK_DOI_INVOICE_CK_MST_INVOICE_TYPE` FOREIGN KEY (`INV_TYPE`) REFERENCES `T_CK_MST_INVOICE_TYPE` (`INVT_ID`),
  CONSTRAINT `FK_CK_DOI_INVOICE_MST_CCY` FOREIGN KEY (`INV_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO INVOICE TYPE TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

