--
-- Table structure for table `T_CK_DO_SHIPPING_LINE_JOURNAL`
--

DROP TABLE IF EXISTS `T_CK_DO_SHIPPING_LINE_JOURNAL`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_DO_SHIPPING_LINE_JOURNAL` (
  `DSLJL_ID` varchar(35) NOT NULL COMMENT 'DO SL JOURNAL ID - UUID',
  `DSLJL_DATE` datetime DEFAULT NULL COMMENT 'DO SL JOURNAL RECORD DATE',
  `DSLJL_SVC` varchar(35) DEFAULT NULL COMMENT 'DO SL JOURNAL REFERENCE SERVICE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `DSLJL_SVC_REF` varchar(255) DEFAULT NULL COMMENT 'DO SL JOURNAL SERVICE REFERENCE - TXN ID',
  `DSLJL_PK` varchar(255) DEFAULT NULL COMMENT 'DO SL JOURNAL PK CODE - 15:40',
  `DSLJL_ACCN` varchar(255) DEFAULT NULL COMMENT 'DO SL JOURNAL ACCOUNT - FROM T_CORE_ACCN_CFG WITH KEY XXX_PAYEE WITH RESPECT TO CO T_CORE_ACCN',
  `DSLJL_DESCRIPTION` varchar(512) DEFAULT NULL COMMENT 'DESCRIPTION - DO SL JOURNAL ACCOUNT + PAYMENT : DO SL JOURNAL ACCOUNT + INVOICE',
  `DSLJL_TEXT` varchar(512) DEFAULT NULL COMMENT 'PAYMENT REFERENCE NUMBER FROM PAYMENT GATEWAY OR DO INVOICE NUMBER',
  `DSLJL_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY FOR THE JOURNAL - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `DSLJL_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'DEBIT AMOUNT',
  `DSLJL_STATUS` char(1) DEFAULT NULL COMMENT 'SHIPMENT STATE STATUS',
  `DSLJL_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DSLJL_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DSLJL_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DSLJL_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DSLJL_ID`),
  KEY `FK_CK_DO_SL_JOURNAL_CK_MST_SERVICE_TYPE` (`DSLJL_SVC`),
  KEY `FK_CK_DO_SL_JOURNAL_MST_CCY` (`DSLJL_CCY`),
  CONSTRAINT `FK_CK_DO_SL_JOURNAL_CK_MST_SERVICE_TYPE` FOREIGN KEY (`DSLJL_SVC`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_DO_SL_JOURNAL_MST_CCY` FOREIGN KEY (`DSLJL_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='MSC JOURNAL TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

