--
-- Table structure for table `T_CK_DOI`
--

DROP TABLE IF EXISTS `T_CK_DOI`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_DOI` (
  `DOI_ID` varchar(35) NOT NULL COMMENT 'DO IMPORT ID - UUID',
  `DOI_PARENT` varchar(35) NOT NULL COMMENT 'DOI PARENT - REFERENCES T_CK_DO:DO_ID',
  `DOI_BL_NO` varchar(255) DEFAULT NULL COMMENT 'DO BL NUMBER - ',
  `DOI_BL` varchar(1024) DEFAULT NULL COMMENT 'BL ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `DOI_DELIVERY_PLACE` varchar(1024) DEFAULT NULL COMMENT 'DO PLACE OF DELIVERY - ',
  `DOI_PAID_THRU_DATE` datetime DEFAULT NULL COMMENT 'DO PAID THRU DATE - 20201001 00:00:00',
  `DOI_RETURN_DEPOT` varchar(1024) DEFAULT NULL COMMENT 'DO RETURN DEPOT',
  `BL_TYPE` varchar(35) DEFAULT NULL COMMENT 'BL TYPE',
  `CONTAINER_NUMBER` varchar(255) DEFAULT NULL COMMENT 'CONTAINER NUMBER',
  `DOI_STATUS` char(1) DEFAULT NULL COMMENT 'DO STATUS - A : I ',
  `DOI_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DOI_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DOI_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DOI_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DOI_ID`),
  KEY `FK_CK_DOI_CK_DO` (`DOI_PARENT`),
  CONSTRAINT `FK_CK_DOI_CK_DO` FOREIGN KEY (`DOI_PARENT`) REFERENCES `T_CK_DO` (`DO_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DELIVERY ORDER IMPORT TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

