DROP TABLE IF EXISTS `T_CK_FORM_CONTROL`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_FORM_CONTROL` (
  `CTRL_ID` varchar(35) NOT NULL COMMENT 'CONTROL ID UUDID ',
  `CTRL_ACCN_TYPE` varchar(35) NOT NULL COMMENT 'CONTROL ACCOUNT TYPE - REFERENCE T_MST_ACCN_TYPE:ATYP_ID',
  `CTRL_ACCN` varchar(35) DEFAULT NULL COMMENT 'OPTIONAL ACCOUNT SPECIFIC CONTROL - REFEREMCE T_CORE_ACCN:ACCN_ID',
  `CTRL_USR_ROLE` varchar(35) NOT NULL COMMENT 'CONTROL USER ROLE - USE T_CORE_ROLES',
  `CTRL_ENTITY_TYPE` varchar(35) NOT NULL COMMENT 'CONTROL ENTITY TYPE - REFERENCE T_CK_MST_ENTITY_TYPE:ENTY_ID',
  `CTRL_ENTITY_STATE` varchar(35) NOT NULL COMMENT 'CONTROL ENTITY STATE - REFERENCE T_CK_MST_ENTITY_STATE:ENST_ID',
  `CTRL_FORM_TYPE` varchar(35) NOT NULL COMMENT 'CONTROL FORM TYPE - REFERENCE T_CK_MST_FORM_TYPE:FMTYP_ID',
  `CTRL_FORM_ACTION` varchar(35) NOT NULL COMMENT 'CONTROL FORM ACTION - REFERENCE T_CK_MST_FORM_ACTION:FMACT_ID',
  `CTRL_FORM_ACTION_MENU` varchar(255) DEFAULT NULL COMMENT 'CONTROL FORM ACTION MENU - OPTIONAL',
  `CTRL_STATUS` char(1) NOT NULL,
  `CTRL_DT_CREATE` datetime DEFAULT NULL,
  `CTRL_UID_CREATE` varchar(35) DEFAULT NULL,
  `CTRL_DT_LUPD` datetime DEFAULT NULL,
  `CTRL_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`CTRL_ID`),
  KEY `IDX_FORMCTRL_CTRL_ACCN_TYPE` (`CTRL_ACCN_TYPE`),
  KEY `IDX_CK_FORM_CONTROL_CTRL_FORM_ACTION` (`CTRL_FORM_ACTION`),
  KEY `IDX_CK_FORM_CONTROL_CTRL_USR_ROLE` (`CTRL_USR_ROLE`),
  KEY `FK_CK_FORM_CONTROL_CORE_ACCN` (`CTRL_ACCN`),
  KEY `FK_CK_FORM_CONTROL_CK_MST_ENTITY_TYPE` (`CTRL_ENTITY_TYPE`),
  KEY `FK_CK_FORM_CONTROL_CK_MST_ENTITY_STATE` (`CTRL_ENTITY_STATE`),
  KEY `FK_CK_FORM_CONTROL_CK_MST_FORM_TYPE` (`CTRL_FORM_TYPE`),
  CONSTRAINT `FK_CK_FORM_CONTROL_CK_MST_ENTITY_STATE` FOREIGN KEY (`CTRL_ENTITY_STATE`) REFERENCES `T_CK_MST_ENTITY_STATE` (`ENST_ID`),
  CONSTRAINT `FK_CK_FORM_CONTROL_CK_MST_ENTITY_TYPE` FOREIGN KEY (`CTRL_ENTITY_TYPE`) REFERENCES `T_CK_MST_ENTITY_TYPE` (`ENTY_ID`),
  CONSTRAINT `FK_CK_FORM_CONTROL_CK_MST_FORM_ACTION` FOREIGN KEY (`CTRL_FORM_ACTION`) REFERENCES `T_CK_MST_FORM_ACTION` (`FMACT_ID`),
  CONSTRAINT `FK_CK_FORM_CONTROL_CK_MST_FORM_TYPE` FOREIGN KEY (`CTRL_FORM_TYPE`) REFERENCES `T_CK_MST_FORM_TYPE` (`FMTYP_ID`),
  CONSTRAINT `FK_CK_FORM_CONTROL_CORE_ACCN` FOREIGN KEY (`CTRL_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_FORM_CONTROL_MST_ACCN_TYPE` FOREIGN KEY (`CTRL_ACCN_TYPE`) REFERENCES `T_MST_ACCN_TYPE` (`ATYP_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
