DROP TABLE IF EXISTS `T_CK_JOB`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB` (
  `JOB_ID` varchar(35) NOT NULL COMMENT 'JOB ID - UUID',
  `JOB_TYPE` varchar(35) NOT NULL COMMENT 'JOB TYPE - REFERENCE T_CK_MST_JOB_TYPE:JBT_ID',
  `JOB_STATE` varchar(35) NOT NULL COMMENT 'JOB STATE - REFERENCE T_CK_MST_JOB_STATE:JBST_ID',
  `JOB_SHIPMENT_TYPE` varchar(35) NOT NULL COMMENT 'JOB SHIPMENT TYPE - REFERENCE T_CK_MST_SHIPMENT_TYPE:SHT_ID',
  `JOB_REFERENCE` varchar(255) DEFAULT NULL COMMENT 'JOB REFERENCE - CUSTOMER REFERENCE',
  `JOB_REMARKS` mediumtext COMMENT 'JOB REMARKS',
  `JOB_DATES` varchar(35) DEFAULT NULL COMMENT 'JOB STATE DATES - REFERENCE T_CK_RECORD_DATE:RCD_ID',
  `JOB_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `JOB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JOB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JOB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JOB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JOB_ID`),
  KEY `FK_CK_JOB_CK_MST_JOB_TYPE` (`JOB_TYPE`),
  KEY `FK_CK_JOB_CK_MST_JOB_STATE` (`JOB_STATE`),
  KEY `FK_CK_JOB_CK_MST_SHIPMENT_TYPE` (`JOB_SHIPMENT_TYPE`),
  KEY `FK_CK_JOB_CK_RECORD_DATE` (`JOB_DATES`),
