--
-- Table structure for table `T_CK_JOB_ATTACH`
--

DROP TABLE IF EXISTS `T_CK_JOB_ATTACH`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_ATTACH` (
  `ATT_ID` varchar(35) NOT NULL COMMENT 'JOB ATTACHMENT ID - UUID',
  `ATT_JOB` varchar(35) NOT NULL COMMENT 'JOB - REFERENCE T_CK_JOB:JOB_ID',
  `ATT_TYPE` varchar(3) NOT NULL COMMENT 'JOB ATTACHMENT TYPE - REFERENCE T_MST_ATT_TYPE:MATT_ID',
  `ATT_NAME` varchar(256) DEFAULT NULL COMMENT 'JOB ATTACHMENT NAME',
  `ATT_LOC` varchar(1024) DEFAULT NULL COMMENT 'JOB ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `ATT_STATUS` char(1) DEFAULT NULL COMMENT 'JOB ATTACHMENT STATUS - A : I ',
  `ATT_REMARKS_VERIFIER` varchar(2048) DEFAULT NULL COMMENT 'REMARKS FROM VERIFIER',
  `ATT_RETURN_FLAG` char(1) DEFAULT NULL COMMENT 'RETURN REQUIRED FLAG',
  `ATT_DT_RETURNED` datetime DEFAULT NULL COMMENT 'DATE WHEN ORIGINAL COPY IS RETURNED AND VERIFIED',
  `ATT_BL_NO` varchar(255) DEFAULT NULL,
  `ATT_DT_VALIDITY` datetime DEFAULT NULL COMMENT 'VALIDITY DATE OF THE ATTACHMENT',
  `ATT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ATT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ATT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ATT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ATT_ID`),
  KEY `FK_CK_JOB_ATTACH_MST_ATT_TYPE` (`ATT_TYPE`),
  KEY `FK_CK_JOB_ATTACH_CK_JOB` (`ATT_JOB`),
  CONSTRAINT `FK_CK_JOB_ATTACH_CK_JOB` FOREIGN KEY (`ATT_JOB`) REFERENCES `T_CK_JOB` (`JOB_ID`),
  CONSTRAINT `FK_CK_JOB_ATTACH_MST_ATT_TYPE` FOREIGN KEY (`ATT_TYPE`) REFERENCES `T_MST_ATT_TYPE` (`MATT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB ATTACHMENT TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

