DROP TABLE IF EXISTS `T_CK_JOB_DOI_CO`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_DOI_CO` (
  `JOB_ID` varchar(35) NOT NULL COMMENT 'JOB ID - UUID',
  `JOB_PARENT` varchar(35) NOT NULL COMMENT 'JOB PARENT - REFERENCE T_CK_JOB:JOB_ID',
  `JOB_AUTHORIZER_ACCN` varchar(35) NOT NULL COMMENT 'JOB AUTHORIZER ACCN - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JOB_AUTHORIZED_PARTY_ACCN` varchar(35) NOT NULL COMMENT 'JOB AUTHORIZED PARTY ACCN - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JOB_ASSIGNED_JOB_FF` varchar(35) DEFAULT NULL COMMENT 'DOI FF JOB THAT IT IS ASSIGNED TO - REFERENCE T_CK_JOB_DOI_FF:JOB_ID',
  `JOB_DO` varchar(35) DEFAULT NULL COMMENT 'JOB DO DETAILS  - REFERENCE T_CK_DOI:DOI_ID',
  `JOB_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `JOB_PAYMENT_VERIFIED_STATE` varchar(35) DEFAULT NULL,
  `JOB_DT_PAYMENT_VERIFIED` datetime DEFAULT NULL,
  `JOB_DOC_VERIFIED_STATE` varchar(35) DEFAULT NULL,
  `JOB_DT_DOC_VERIFIED` datetime DEFAULT NULL,
  `JOB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JOB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JOB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JOB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JOB_ID`),
  KEY `FK_CK_JOB_DOI_CO_CK_JOB` (`JOB_PARENT`),
  KEY `FK_CK_JOB_DOI_CO_CK_DOI` (`JOB_DO`),
  KEY `FK_CK_JOB_DOI_CO_CORE_ACCN1` (`JOB_AUTHORIZER_ACCN`),
  KEY `FK_CK_JOB_DOI_CK_JOB_DOI_FF` (`JOB_AUTHORIZED_PARTY_ACCN`),
  KEY `FK_CK_JOB_DOI_CK_JOB_DOI_FF_idx` (`JOB_ASSIGNED_JOB_FF`),
  CONSTRAINT `FK_CK_JOB_DOI_CK_JOB_DOI_FF` FOREIGN KEY (`JOB_ASSIGNED_JOB_FF`) REFERENCES `T_CK_JOB_DOI_FF` (`JOB_ID`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_CK_DOI` FOREIGN KEY (`JOB_DO`) REFERENCES `T_CK_DOI` (`DOI_ID`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_CK_JOB` FOREIGN KEY (`JOB_PARENT`) REFERENCES `T_CK_JOB` (`JOB_ID`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_CORE_ACCN1` FOREIGN KEY (`JOB_AUTHORIZER_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_CORE_ACCN2` FOREIGN KEY (`JOB_AUTHORIZED_PARTY_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO IMPORT CARGO OWNER JOB TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

