--
-- Table structure for table `T_CK_JOB_DOI_FF`
--

DROP TABLE IF EXISTS `T_CK_JOB_DOI_FF`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_DOI_FF` (
  `JOB_ID` varchar(35) NOT NULL COMMENT 'JOB ID - UUID',
  `JOB_PARENT` varchar(35) NOT NULL COMMENT 'JOB PARENT - REFERENCE T_CK_JOB:JOB_ID',
  `JOB_AUTHORIZED_PARTY_ACCN` varchar(35) NOT NULL COMMENT 'JOB AUTHORIZED PARTY ACCN - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JOB_SL_ACCN` varchar(35) NOT NULL,
  `JOB_NO_DO` smallint DEFAULT '0' COMMENT 'NUMBER OF DOs ATTACH TO JOB - MUST TALLY WITH T_CK_JOB_DOI_FF_DO RECORDS',
  `JOB_INVOICE` varchar(1024) NOT NULL COMMENT 'JOB PROFOMA INVOICE PDF FULL PATH',
  `JOB_DT_PAID` datetime DEFAULT NULL COMMENT 'JOB PAID DATE',
  `JOB_PAYMENT_VERIFIED_STATE` varchar(35) DEFAULT NULL COMMENT 'PAYMENT_VERIFIED',
  `JOB_DT_PAYMENT_VERIFIED` datetime DEFAULT NULL COMMENT 'JOB PAYMENT VERIFIED DATE',
  `JOB_DOC_VERIFIED_STATE` varchar(35) DEFAULT NULL COMMENT 'VERIFIED, PENDING_RETURN',
  `JOB_DT_DOC_VERIFIED` datetime DEFAULT NULL COMMENT 'JOB PAYMENT VERIFIED DATE',
  `JOB_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `JOB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JOB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JOB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JOB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JOB_ID`),
  KEY `FK_CK_JOB_DOI_CO_FF_JOB` (`JOB_PARENT`),
  KEY `FK_CK_JOB_DOI_CO_CORE_ACCN` (`JOB_AUTHORIZED_PARTY_ACCN`),
  KEY `FK_CK_JOB_DOI_SL_ACCN_idx` (`JOB_SL_ACCN`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_CORE_ACCN` FOREIGN KEY (`JOB_AUTHORIZED_PARTY_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_JOB_DOI_CO_FF_JOB` FOREIGN KEY (`JOB_PARENT`) REFERENCES `T_CK_JOB` (`JOB_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO IMPORT FREIGHT FORWARDERS JOB TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

