--
-- Table structure for table `T_CK_JOB_DOI_FF_DO`
--

DROP TABLE IF EXISTS `T_CK_JOB_DOI_FF_DO`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_DOI_FF_DO` (
  `JDO_ID` varchar(35) NOT NULL COMMENT 'JOBL ID - UUID',
  `JDO_JOB` varchar(35) NOT NULL COMMENT 'JOB ID FOR THE BL - REFERENCE T_CK_JOB_DOI_FF:JOB_ID',
  `JDO_AUTHORIZER_ACCN` varchar(35) NOT NULL COMMENT 'JOB AUTHORIZER ACCN - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JDO_AUTHORIZED_PARTY_ACCN` varchar(35) NOT NULL COMMENT 'JOB AUTHORIZED PARTY ACCN - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JDO_DO` varchar(35) DEFAULT NULL COMMENT 'JOB DETAILS - REFERENCE T_CK_DOI:DOI_ID',
  `JDO_JOB_CO` varchar(35) DEFAULT NULL COMMENT 'JOB CO IF PRESENT - REFERENCE T_CK_JOB:JOB_ID',
  `JDO_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `JDO_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JDO_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JDO_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
