--
-- Table structure for table `T_CK_JOB_QUERY`
--

DROP TABLE IF EXISTS `T_CK_JOB_QUERY`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_QUERY` (
  `QRY_ID` varchar(35) NOT NULL COMMENT 'QUERY ID - UUID',
  `QRY_JOB` varchar(35) NOT NULL COMMENT 'JOB QUERY JOB - REFERENCE REFERENCE T_CK_JOB:JOB_ID',
  `QRY_REQUESTER` varchar(35) DEFAULT NULL COMMENT 'QUERY REQUESTER - REFERENCE T_CORE_USR:USR_UID',
  `QRY_DT_QUERY` datetime DEFAULT NULL COMMENT 'QUERY DATE',
  `QRY_QUERY` mediumtext COMMENT 'QUERY',
  `QRY_RESPONDER` varchar(35) DEFAULT NULL COMMENT 'QUERY RESPONDER - REFERENCE T_CORE_USR:USR_UID',
  `QRY_DT_RESPONSE` datetime DEFAULT NULL COMMENT 'JOB QUERY DATE',
  `QRY_RESPONSE` mediumtext COMMENT 'RESPONSE',
  `QRY_STATUS` char(1) DEFAULT NULL COMMENT 'JOB ATTACHMENT STATUS - A : I ',
  `QRY_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `QRY_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `QRY_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `QRY_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`QRY_ID`),
  KEY `FK_CK_JOB_QUERY_CK_JOB` (`QRY_JOB`),
  KEY `FK_CK_JOB_QUERY_CORE_USR1` (`QRY_REQUESTER`),
  KEY `FK_CK_JOB_QUERY_CORE_USR2` (`QRY_RESPONDER`),
  CONSTRAINT `FK_CK_JOB_QUERY_CK_JOB` FOREIGN KEY (`QRY_JOB`) REFERENCES `T_CK_JOB` (`JOB_ID`),
  CONSTRAINT `FK_CK_JOB_QUERY_CORE_USR1` FOREIGN KEY (`QRY_REQUESTER`) REFERENCES `T_CORE_USR` (`USR_UID`),
  CONSTRAINT `FK_CK_JOB_QUERY_CORE_USR2` FOREIGN KEY (`QRY_RESPONDER`) REFERENCES `T_CORE_USR` (`USR_UID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB QUERY TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

