--
-- Table structure for table `T_CK_JOB_TRUCK`
--

DROP TABLE IF EXISTS `T_CK_JOB_TRUCK`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_JOB_TRUCK` (
  `JOB_ID` varchar(35) NOT NULL COMMENT 'JOB ID - UUID',
  `JOB_PARENT` varchar(35) NOT NULL COMMENT 'JOB PARENT - REFERENCE T_CK_JOB:JOB_ID',
  `JOB_PARTY_TO` varchar(35) DEFAULT NULL COMMENT 'JOB PARTY TRUCKING OPERATOR - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JOB_PARTY_CO_FF` varchar(35) DEFAULT NULL COMMENT 'JOB PARTY CARGO OWNER OR FORWARDER - REFERENCE T_CORE_ACCN:ACCN_ID',
  `JOB_DT_BOOKING` datetime DEFAULT NULL COMMENT 'JOB BOOKING DATE',
  `JOB_DT_PLAN` datetime DEFAULT NULL COMMENT 'JOB PLAN DATE',
  `JOB_DT_DELIVERY` datetime DEFAULT NULL COMMENT 'JOB DELIVERY DATE',
  `JOB_CONTACT_TO` varchar(35) DEFAULT NULL COMMENT 'JOB CONTACT TRUCKING OPERATOR - REFERENCE T_CK_CT_CONTACT_DETAIL:CD_ID',
  `JOB_CONTACT_CO_FF` varchar(35) DEFAULT NULL COMMENT 'JOB CONTACT CARGO OWNER OR FORWARDER - REFERENCE T_CK_CT_CONTACT_DETAIL:CD_ID',
  `JOB_VEH_TYPE` varchar(35) DEFAULT NULL COMMENT 'VEHICLE TYPE - REFERENCES T_CK_CT_MST_VEH_TYPE:VHTY_ID',
  `JOB_NO_TRIPS` smallint DEFAULT '0' COMMENT 'NUMBER OF TRIPS IN JOB',
  `JOB_VEH` varchar(35) DEFAULT NULL COMMENT 'VEHICLE FOR JOB - REFERENCES T_CK_CT_VEH:VH_ID',
  `JOB_DRV` varchar(35) DEFAULT NULL COMMENT 'DRIVER FOR JOB - REFERENCES T_CK_CT_DRV:DRV_ID',
  `JOB_TO_INVOICE` varchar(35) DEFAULT NULL COMMENT 'TO INVOICE - REFERENCES T_CK_CT_TO_INVOICE:INV_ID',
  `JOB_INVOICER_DEBIT_NOTE` varchar(35) DEFAULT NULL COMMENT 'TO DN - REFERENCES T_CK_CT_DEBIT_NOTE:DN_ID',
  `JOB_INVOICEE_DEBIT_NOTE` varchar(35) DEFAULT NULL COMMENT 'CO/FF DN - REFERENCES T_CK_CT_DEBIT_NOTE:DN_ID',
  `JOB_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `JOB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JOB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JOB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JOB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JOB_ID`),
  KEY `FK_CK_JOB_TRUCK_CO_CK_JOB` (`JOB_PARENT`),
  KEY `FK_CK_JOB_TRUCK_CORE_ACCN1` (`JOB_PARTY_TO`),
  KEY `FK_CK_JOB_TRUCK_CORE_ACCN2` (`JOB_PARTY_CO_FF`),
  KEY `FK_CK_JOB_TRUCK_CK_CT_CONTACT_DETAIL1` (`JOB_CONTACT_TO`),
  KEY `FK_CK_JOB_TRUCK_CK_CT_CONTACT_DETAIL2` (`JOB_CONTACT_CO_FF`),
  KEY `FK_CK_JOB_TRUCK_CK_CT_MST_VEH_TYPE` (`JOB_VEH_TYPE`),
  KEY `FK_CK_JOB_TRUCK_CK_CT_DRV` (`JOB_VEH`),
  KEY `FK_CK_JOB_TRUCK_CK_CT_TO_INVOICE` (`JOB_TO_INVOICE`),
  KEY `FK_CK_JOB_TRUCK_K_CT_DEBIT_NOTE1` (`JOB_INVOICER_DEBIT_NOTE`),
  KEY `FK_CK_JOB_TRUCK_K_CT_DEBIT_NOTE2` (`JOB_INVOICEE_DEBIT_NOTE`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_CONTACT_DETAIL1` FOREIGN KEY (`JOB_CONTACT_TO`) REFERENCES `T_CK_CT_CONTACT_DETAIL` (`CD_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_CONTACT_DETAIL2` FOREIGN KEY (`JOB_CONTACT_CO_FF`) REFERENCES `T_CK_CT_CONTACT_DETAIL` (`CD_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_DRV` FOREIGN KEY (`JOB_VEH`) REFERENCES `T_CK_CT_DRV` (`DRV_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_MST_VEH_TYPE` FOREIGN KEY (`JOB_VEH_TYPE`) REFERENCES `T_CK_CT_MST_VEH_TYPE` (`VHTY_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_TO_INVOICE` FOREIGN KEY (`JOB_TO_INVOICE`) REFERENCES `T_CK_CT_TO_INVOICE` (`INV_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CK_CT_VEH` FOREIGN KEY (`JOB_VEH`) REFERENCES `T_CK_CT_VEH` (`VH_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CO_CK_JOB` FOREIGN KEY (`JOB_PARENT`) REFERENCES `T_CK_JOB` (`JOB_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CORE_ACCN1` FOREIGN KEY (`JOB_PARTY_TO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_CORE_ACCN2` FOREIGN KEY (`JOB_PARTY_CO_FF`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_K_CT_DEBIT_NOTE1` FOREIGN KEY (`JOB_INVOICER_DEBIT_NOTE`) REFERENCES `T_CK_CT_DEBIT_NOTE` (`DN_ID`),
  CONSTRAINT `FK_CK_JOB_TRUCK_K_CT_DEBIT_NOTE2` FOREIGN KEY (`JOB_INVOICEE_DEBIT_NOTE`) REFERENCES `T_CK_CT_DEBIT_NOTE` (`DN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TRUCK JOB TABLE';
