DROP TABLE IF EXISTS `T_CK_PAYMENT_AUDIT`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_PAYMENT_AUDIT` (
  `PYA_ID` varchar(35) NOT NULL COMMENT 'PAYMENT AUDIT ID - UUID',
  `PYA_TYPE` varchar(35) NOT NULL COMMENT 'PAYMENT AUDIT TYPE - REFERENCE T_CK_MST_PAYMENT_AUDIT_TYPE:PATY_ID',
  `PYA_REFERENCE` varchar(1024) DEFAULT NULL COMMENT 'PAYMENT REFERENCE - UUID PASS TO PAYMENT GATEWAY TO LINK TO CALLBACK',
  `PYA_REQ` mediumtext COMMENT 'PAYMENT REQUEST JSON',
  `PYA_RESP` mediumtext COMMENT 'PAYMENT RESPONSE JSON',
  `PYA_CB` mediumtext COMMENT 'PAYMENT CALLBACK JSON',
  `PYA_REMARK` mediumtext COMMENT 'PAYMENT CALLBACK JSON',
  `PYA_STATE` varchar(3) DEFAULT NULL,
  `PYA_STATUS` char(1) DEFAULT NULL COMMENT 'PAYMENT AUDIT TYPE STATUS',
  `PYA_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `PYA_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `PYA_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `PYA_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`PYA_ID`),
  KEY `FK_CK_DO_PAYMENT_AUDIT_CK_MST_PAYMENT_AUDIT_TYPE` (`PYA_TYPE`),
  CONSTRAINT `FK_CK_DO_PAYMENT_AUDIT_CK_MST_PAYMENT_AUDIT_TYPE` FOREIGN KEY (`PYA_TYPE`) REFERENCES `T_CK_MST_PAYMENT_AUDIT_TYPE` (`PATY_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO PAYMENT TRANSACTION';
/*!40101 SET character_set_client = @saved_cs_client */;

