CREATE TABLE `T_CK_RECORD_DATE` (
  `RCD_ID` varchar(35) NOT NULL COMMENT 'DATE  ID - EXP : IMP',
  `RCD_DT_DRFT` datetime DEFAULT NULL COMMENT 'RECORD DRAFT DATE',
