  `RCD_DT_COMPLETE` datetime DEFAULT NULL COMMENT 'RECORD COMPLETED DATE',
  `RCD_DT_CANCEL` datetime DEFAULT NULL COMMENT 'RECORD CANCELLED DATE',
  `RCD_DT_REJECT` datetime DEFAULT NULL COMMENT 'RECORD REJECTED DATE',
  `RCD_DT_DELETE` datetime DEFAULT NULL COMMENT 'RECORD DELTED DATE',
  PRIMARY KEY (`RCD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='RECORD DATE TABLE';
