--
-- Table structure for table `T_CK_SVC_AUTH`
--

DROP TABLE IF EXISTS `T_CK_SVC_AUTH`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_SVC_AUTH` (
  `SVAU_ID` varchar(35) NOT NULL COMMENT 'SERVICE AUTHORISATION ID - UUID',
  `SVAU_SERVICE` varchar(35) DEFAULT NULL COMMENT 'SERVICE AUTHORISATION SERVICE - REFERENCE T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `SVAU_STATE` varchar(35) DEFAULT NULL COMMENT 'SERVICE AUTHORISATION STATE - REFERENCE T_CK_MST_AUTH_STATE:AUST_ID',
  `SVAU_ACCN_AUTHORIZER` varchar(35) DEFAULT NULL COMMENT 'AUTHORIZER ACCN  - REFERENCE T_CORE_ACCN:ACCN_ID',
  `SVAU_USR_AUTHORIZER` varchar(35) DEFAULT NULL COMMENT 'AUTHORIZER USR  - REFERENCE T_CORE_USR:USR_UID',
  `SVAU_POSITION_AUTHORIZER` varchar(255) DEFAULT NULL COMMENT 'AUTHORIZER USR POSITION - MANAGER',
  `SVAU_ACCN_AUTHORIZED` varchar(35) DEFAULT NULL COMMENT 'AUTHORIZED PARTY ACCN  - REFERENCE T_CORE_ACCN:ACCN_ID',
  `SVAU_USR_AUTHORIZED` varchar(35) DEFAULT NULL COMMENT 'AUTHORIZER PARTY USR  - REFERENCE T_CORE_USR:USR_UID',
  `SVAU_POSITION_AUTHORIZED` varchar(255) DEFAULT NULL COMMENT 'AUTHORIZED PARTY USR POSITION - MANAGER',
  `SVAU_ACCN_SERVICE` varchar(35) DEFAULT NULL COMMENT 'SERVICE PROVIDER ACCN  - REFERENCE T_CORE_ACCN:ACCN_ID',
  `SVAU_DT_SERVICE_START` datetime DEFAULT NULL COMMENT 'AUTHORISATION START DATE',
  `SVAU_DT_SERVICE_VALID` datetime DEFAULT NULL COMMENT 'AUTHORISATION VALIDILITY DATE',
  `SVAU_REMARKS_AUTHORIZER` mediumtext COMMENT 'AUTHORIZER REMARKS',
  `SVAU_REMARKS_AUTHORIZED` mediumtext COMMENT 'AUTHORIZER PARTY REMARKS',
  `SVAU_STATUS` char(1) DEFAULT NULL COMMENT 'AUTHORISATION STATE STATUS',
  `SVAU_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SVAU_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SVAU_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SVAU_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SVAU_ID`),
  KEY `FK_CK_SERVICE_AUTH_CK_MST_SERVICE_TYPE` (`SVAU_SERVICE`),
  KEY `FK_CK_SERVICE_AUTH_CK_MST_AUTH_STATE` (`SVAU_STATE`),
  KEY `FK_CK_SERVICE_AUTH_CORE_ACCN1` (`SVAU_ACCN_AUTHORIZER`),
  KEY `FK_CK_SERVICE_AUTH_CORE_USR1` (`SVAU_USR_AUTHORIZER`),
  KEY `FK_CK_SERVICE_AUTH_CORE_ACCN2` (`SVAU_ACCN_AUTHORIZED`),
  KEY `FK_CK_SERVICE_AUTH_CORE_USR2` (`SVAU_USR_AUTHORIZED`),
  KEY `FK_CK_SERVICE_AUTH_CORE_ACCN3` (`SVAU_ACCN_SERVICE`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CK_MST_AUTH_STATE` FOREIGN KEY (`SVAU_STATE`) REFERENCES `T_CK_MST_AUTH_STATE` (`AUST_ID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CK_MST_SERVICE_TYPE` FOREIGN KEY (`SVAU_SERVICE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CORE_ACCN1` FOREIGN KEY (`SVAU_ACCN_AUTHORIZER`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CORE_ACCN2` FOREIGN KEY (`SVAU_ACCN_AUTHORIZED`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CORE_ACCN3` FOREIGN KEY (`SVAU_ACCN_SERVICE`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CORE_USR1` FOREIGN KEY (`SVAU_USR_AUTHORIZER`) REFERENCES `T_CORE_USR` (`USR_UID`),
  CONSTRAINT `FK_CK_SERVICE_AUTH_CORE_USR2` FOREIGN KEY (`SVAU_USR_AUTHORIZED`) REFERENCES `T_CORE_USR` (`USR_UID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='AUTHORISATION STATE TABLE';
/*!40101 SET character_set_client = @saved_cs_client */;

