CREATE TABLE `T_CK_SVC_JOURNAL` (
  `SVJL_ID` varchar(35) NOT NULL COMMENT 'SERVICE JOURNAL ID - UUID',
  `SVJL_DATE` datetime DEFAULT NULL COMMENT 'SERVICE JOURNAL RECORD DATE',
  `SVJL_SVC` varchar(35) DEFAULT NULL COMMENT 'SERVICE JOURNAL REFERENCE SERVICE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `SVJL_SVC_REF` varchar(255) DEFAULT NULL COMMENT 'SERVICE JOURNAL SERVICE REFERENCE - TXN ID',
  `SVJL_TXN_CODE` varchar(255) DEFAULT NULL COMMENT 'SERVICE JOURNAL TXN CODE - DOC_INVOICE:DOC_PAYMENT:DOE_INVOICE:DOE_PAYMENT',
  `SVJL_DESCRIPTION` varchar(512) DEFAULT NULL COMMENT 'SERVICE JOURNAL DESCRIPTION - INVOICE FOR DO:PAYMENT FOR DO',
  `SVJL_COA` varchar(255) DEFAULT NULL COMMENT 'SERVICE JOURNAL CHARTS OF ACCOUNT - UNIQUE ACCOUNT CODE FOR EACH PAYER E.G. DO_(T_CORE_ACCN:ACCN_ID)',
  `SVJL_ACCN_NAME` varchar(255) DEFAULT NULL COMMENT 'SERVICE JOURNAL ACCOUNT NAME - [SERVICE]_(T_CORE_ACCN:ACCN_NAME)',
  `SVJL_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY FOR THE JOURNAL - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `SVJL_DEBIT` decimal(15,2) DEFAULT '0.00' COMMENT 'DEBIT AMOUNT',
  `SVJL_CREDIT` decimal(15,2) DEFAULT '0.00' COMMENT 'CREDIT AMOUNT',
  `SVJL_STATUS` char(1) DEFAULT NULL COMMENT 'SHIPMENT STATE STATUS',
  `SVJL_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SVJL_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SVJL_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SVJL_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SVJL_ID`),
  KEY `FK_CK_SVC_JOURNAL_CK_MST_SERVICE_TYPE` (`SVJL_SVC`),
  KEY `FK_CK_SVC_JOURNAL_MST_CCY` (`SVJL_CCY`),
  CONSTRAINT `FK_CK_SVC_JOURNAL_CK_MST_SERVICE_TYPE` FOREIGN KEY (`SVJL_SVC`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SVC_JOURNAL_MST_CCY` FOREIGN KEY (`SVJL_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
