DROP TABLE IF EXISTS `T_CK_SVC_SUB`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_SVC_SUB` (
  `SUB_ID` varchar(35) NOT NULL COMMENT 'SERVICE SUBSCRIPTION ID - UUID',
  `SUB_TYPE` varchar(35) DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION TYPE - REFERENCE T_CK_MST_SERVICE_TYPE:SSST_ID',
  `SUB_STATE` varchar(35) DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION STATE - REFERENCE T_CK_MST_SVC_SUB_STATE:SSST_ID',
  `SUB_SUBSCRIBER` varchar(35) DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION ACCOUNT - REFERENCE T_CORE_ACCN:ACCN_ID',
  `SUB_DT_START` datetime DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION START DATE',
  `SUB_DT_VALID` datetime DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION VALIDILITY DATE',
  `SUB_AUTO_RENEW` char(1) DEFAULT 'N' COMMENT 'SERVICE SUBSCRIPTION AUTO RENEWAL - Y:N',
  `SUB_UID_VERIFY` varchar(35) DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION VERIFIY BY',
  `SUB_DT_VERIFY` datetime DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION VERIFIY DATE',
  `SUB_UID_APPROVE` varchar(35) DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION APPROVE BY',
  `SUB_DT_APPROVE` datetime DEFAULT NULL COMMENT 'SERVICE SUBSCRIPTION APPROVE DATE',
  `SUB_STATUS` char(1) DEFAULT NULL COMMENT 'SERVICE TYPE STATUS',
  `SUB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SUB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SUB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SUB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SUB_ID`),
  KEY `FK_CK_SVC_SUB_CK_MST_SERVICE_TYPE` (`SUB_TYPE`),
  KEY `FK_CK_SVC_SUB_CK_MST_SVC_SUB_STATE` (`SUB_STATE`),
  KEY `FK_CK_SVC_SUB_CORE_ACCN` (`SUB_SUBSCRIBER`),
  CONSTRAINT `FK_CK_SVC_SUB_CK_MST_SERVICE_TYPE` FOREIGN KEY (`SUB_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SVC_SUB_CK_MST_SVC_SUB_STATE` FOREIGN KEY (`SUB_STATE`) REFERENCES `T_CK_MST_SVC_SUB_STATE` (`SSST_ID`),
  CONSTRAINT `FK_CK_SVC_SUB_CORE_ACCN` FOREIGN KEY (`SUB_SUBSCRIBER`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SERVICE SUBSCRIPTION TABLE';
