  `CBLB_STATUS` char(1) NOT NULL COMMENT 'I - Inactive, A - Active',
  `CBLB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'Created By User',
  `CBLB_DT_CREATE` datetime DEFAULT NULL COMMENT 'Created Date',
  `CBLB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Update by User',
  `CBLB_DT_LUPD` datetime DEFAULT NULL COMMENT 'Update Date',
  PRIMARY KEY (`CBLB_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
