  `CBC_RESULT` varchar(1) DEFAULT NULL COMMENT 'T: SUCCESSFUL, F: FAILED',
  `CBC_FAIL_LOG` varchar(5000) DEFAULT NULL COMMENT 'ANNOUNCEMENT CONTENT',
  `CBC_REFERENCE` varchar(255) DEFAULT NULL COMMENT 'doc NO. ',
  `CBC_STATUS` char(1) NOT NULL COMMENT 'I - Inactive, A - Active',
  `CBC_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'Created By User',
  `CBC_DT_CREATE` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Created Date',
  `CBC_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Update by User',
  `CBC_DT_LUPD` datetime DEFAULT NULL COMMENT 'Update Date',
  PRIMARY KEY (`CBC_ID`),
  KEY `FKY_CBC_APPSCODE` (`CBC_APPSCODE`),
