--
-- Table structure for table `T_CORE_PERM_EX`
--

DROP TABLE IF EXISTS `T_CORE_PERM_EX`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_PERM_EX` (
  `PERM_ID` varchar(35) NOT NULL COMMENT 'PERM_ID',
  `PERM_GROUP` char(1) NOT NULL DEFAULT 'Y' COMMENT 'Y: group permission N: not group permission',
  `PERM_APPS` varchar(35) DEFAULT NULL COMMENT 'Reference to T_CORE_APPS',
  `PERM_MODULE` varchar(35) DEFAULT NULL COMMENT 'Reference to T_CORE_MODULE',
  `PERM_TYPE` char(1) NOT NULL DEFAULT 'E' COMMENT 'E: Entity S: Service M: Menu',
  `PERM_SERVICE` varchar(35) DEFAULT NULL COMMENT 'Reference to T_CORE_MODULE_SERVICE',
  `PERM_SERVICE_URI` varchar(255) DEFAULT NULL COMMENT 'URI for permisison service',
  `PERM_MENU` varchar(35) DEFAULT NULL COMMENT 'Reference to T_CORE_MENU_EX',
  `PERM_MENU_NAME` varchar(255) DEFAULT NULL COMMENT 'Display name of the menu in English',
  `PERM_DOC_TYPE` varchar(35) DEFAULT NULL COMMENT 'Reference to T_MST_DOC_TYPE',
  `PERM_DOC_CODE` varchar(35) DEFAULT NULL COMMENT 'Reference to T_MST_DOC_CODE',
  `PERM_ACTION` varchar(35) DEFAULT NULL COMMENT 'Reference to T_MST_PERM_ACTION',
  `PERM_DESC` varchar(256) DEFAULT NULL COMMENT 'Descrption of the permission',
  `PERM_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'Descrption of the permission in other language',
  `PERM_ACCESS` varchar(2) NOT NULL DEFAULT 'RW' COMMENT 'R: read only permission W:write permission RW: read write permission',
  `PERM_DT_ACTIVE` datetime NOT NULL COMMENT 'Specifies the date where the permission is activated',
  `PERM_DT_DEACTIVE` datetime DEFAULT NULL COMMENT 'Specifies the date where the permission is de-activated',
  `PERM_STATUS` char(1) NOT NULL COMMENT 'Record status',
  `PERM_DT_CREATE` datetime NOT NULL COMMENT 'Record datetime created',
  `PERM_UID_CREATE` varchar(35) NOT NULL COMMENT 'Record user created',
  `PERM_DT_LUPD` datetime DEFAULT NULL COMMENT 'Record datetime last updated',
  `PERM_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Record user last updated',
  PRIMARY KEY (`PERM_ID`),
  UNIQUE KEY `UN_TPERM_DTDC` (`PERM_APPS`,`PERM_DOC_TYPE`,`PERM_DOC_CODE`,`PERM_GROUP`,`PERM_ACTION`),
  UNIQUE KEY `UN_TPERM_SERVICE` (`PERM_APPS`,`PERM_SERVICE`,`PERM_SERVICE_URI`),
  KEY `FK_TPERM_DOC_CODE` (`PERM_DOC_CODE`),
  KEY `FK_TPERM_DOC_TYPE` (`PERM_DOC_TYPE`),
  KEY `FK_TPERM_MENU` (`PERM_MENU`),
  KEY `FK_TPERM_MODULE` (`PERM_MODULE`),
  KEY `FK_TPERM_MOD_SERVICE` (`PERM_SERVICE`),
  KEY `FK_TPERM_PERM_ACTION` (`PERM_ACTION`),
  CONSTRAINT `FK_TPERM_CORE_APPS` FOREIGN KEY (`PERM_APPS`) REFERENCES `T_CORE_APPS` (`APPS_CODE`),
  CONSTRAINT `FK_TPERM_DOC_CODE` FOREIGN KEY (`PERM_DOC_CODE`) REFERENCES `T_MST_DOC_CODE` (`MDC_CODE`),
  CONSTRAINT `FK_TPERM_DOC_TYPE` FOREIGN KEY (`PERM_DOC_TYPE`) REFERENCES `T_MST_DOC_TYPE` (`MDT_CODE`),
  CONSTRAINT `FK_TPERM_MENU` FOREIGN KEY (`PERM_MENU`) REFERENCES `T_CORE_MENU_EX` (`MENU_ID`),
  CONSTRAINT `FK_TPERM_MOD_SERVICE` FOREIGN KEY (`PERM_SERVICE`) REFERENCES `T_CORE_MODULE_SERVICE` (`MODS_ID`),
  CONSTRAINT `FK_TPERM_MODULE` FOREIGN KEY (`PERM_MODULE`) REFERENCES `T_CORE_MODULE` (`MOD_ID`),
  CONSTRAINT `FK_TPERM_PERM_ACTION` FOREIGN KEY (`PERM_ACTION`) REFERENCES `T_MST_PERM_ACTION` (`PRMA_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='Permissions Extension';
/*!40101 SET character_set_client = @saved_cs_client */;

