  `SESS_TIME_PRINCIPAL_CACHE` datetime DEFAULT CURRENT_TIMESTAMP,
  `SESS_CURRGRP_TD` varchar(35) DEFAULT NULL,
  `SESS_CURRGRP_FWD` varchar(35) DEFAULT NULL,
  `SESS_CURRGRP_SHP` varchar(35) DEFAULT NULL,
  `SESS_CURRGRP_CON` varchar(35) DEFAULT NULL,
  `SESS_OBJ` longblob,
  PRIMARY KEY (`SESS_SID`)
