--
-- Table structure for table `T_CORE_SUB_MENU`
--

DROP TABLE IF EXISTS `T_CORE_SUB_MENU`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_SUB_MENU` (
  `SUB_MENU_ID` varchar(35) NOT NULL,
  `SUB_MAIN_MENU_ID` varchar(35) NOT NULL,
  `SUB_MENU_CSS` varchar(30) DEFAULT NULL,
  `SUB_MENU_ORDER` int NOT NULL,
  `SUB_MENU_LEVEL_ONE_MENU_ID` varchar(35) DEFAULT NULL,
  `SUB_MENU_DESCRIPTION` varchar(150) NOT NULL,
  `SUB_MENU_URL` varchar(35) DEFAULT NULL,
  `SUB_MENU_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'The last update user.',
  `SUB_MENU_DT_LUPD` datetime DEFAULT NULL COMMENT 'The last update date.',
  `SUB_MENU_UID_CREATE` varchar(35) NOT NULL COMMENT 'The user who created,',
  `SUB_MENU_DT_CREATE` datetime NOT NULL COMMENT 'Default to CURRENT_DATE',
  `SUB_MENU_DT_DEACTIVE` datetime DEFAULT NULL COMMENT 'Specifies the date where the sub menu is de-activated',
  `SUB_MENU_DT_ACTIVE` datetime NOT NULL COMMENT 'Specifies the date where the sub menu is activated.',
  `SUB_MENU_STATUS` char(1) NOT NULL COMMENT 'A is active,I is inactive,Default is A',
  PRIMARY KEY (`SUB_MENU_ID`),
  KEY `fk_t_mst_menu_menu_sub_menu_id_t_mst_menu_menu_id` (`SUB_MAIN_MENU_ID`),
  KEY `t_core_SUB_menu__url_t_core_uri_uri_id` (`SUB_MENU_URL`),
  KEY `t_core_sub_menu__menu_id_t_core_sub_menu_level_one_menu_id` (`SUB_MENU_LEVEL_ONE_MENU_ID`),
  CONSTRAINT `fk_t_mst_menu_menu_sub_menu_id_t_mst_menu_menu_id` FOREIGN KEY (`SUB_MAIN_MENU_ID`) REFERENCES `T_CORE_MENU` (`MENU_ID`),
  CONSTRAINT `t_core_sub_menu__menu_id_t_core_sub_menu_level_one_menu_id` FOREIGN KEY (`SUB_MENU_LEVEL_ONE_MENU_ID`) REFERENCES `T_CORE_SUB_MENU` (`SUB_MENU_ID`),
  CONSTRAINT `t_core_SUB_menu__url_t_core_uri_uri_id` FOREIGN KEY (`SUB_MENU_URL`) REFERENCES `T_CORE_URI` (`URI_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

