--
-- Table structure for table `T_CORE_URI`
--

DROP TABLE IF EXISTS `T_CORE_URI`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_URI` (
  `URI_ID` varchar(35) NOT NULL COMMENT 'Contains the unique ID for this URI. <first 5-char of T_CORE_APPS.APPS_CODE>:<1-10-char representation of function provided>\nEg. CSNWP:MSGLIST\n',
  `URI_APPS_CODE` varchar(35) NOT NULL COMMENT 'Contains the application code that this URI is created under',
  `URI_NAME` varchar(256) NOT NULL COMMENT 'Holds the user-friendly name assigned to this URI',
  `URI_DESC` varchar(4096) DEFAULT NULL COMMENT 'Description of whaT this URI is for',
  `URI_STATUS` char(1) NOT NULL COMMENT 'Status of URL A â active; I â InactiveDefault, is A',
  `URI_TYPE` varchar(35) NOT NULL COMMENT 'URL â for portal URLs, WS - webservice',
  `URI_DETAILS` varchar(1024) DEFAULT NULL COMMENT 'For portal, this should take reference from T_CORE_APPS.APP_URI_BASE_PATH',
  `URI_PARAM_1` varchar(1024) DEFAULT NULL COMMENT 'URI_PARAM_1 to URI_PARAM_5 can be used to store URI specific parameters. ',
  `URI_PARAM_2` varchar(1024) DEFAULT NULL,
  `URI_PARAM_3` varchar(1024) DEFAULT NULL,
  `URI_PARAM_4` varchar(1024) DEFAULT NULL,
  `URI_PARAM_5` varchar(1024) DEFAULT NULL,
  `URI_DT_ACTIVE` datetime NOT NULL COMMENT 'If not null, will specify the date where the application will be activated.\nDefaulted to CURR_DATE',
  `URI_DT_DEACTIVE` datetime DEFAULT NULL COMMENT 'If not null, will specify the date where the application will be de-activated.  URI_STATUS will be set to âIâ upon deactivated. If null, indicates that the application will not be de-activated.',
  `URI_DT_CREATE` datetime NOT NULL,
  `URI_UID_CREATE` varchar(35) NOT NULL,
  `URI_DT_LUPD` datetime DEFAULT NULL,
  `URI_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`URI_ID`),
  KEY `FKY__T_CORE_APPS__APPSCODE` (`URI_APPS_CODE`),
  KEY `FKY__T_MST_URI_TYPE__MURIT_ID_idx` (`URI_TYPE`),
  CONSTRAINT `FKY__T_CORE_APPS__APPSCODE` FOREIGN KEY (`URI_APPS_CODE`) REFERENCES `T_CORE_APPS` (`APPS_CODE`),
  CONSTRAINT `FKY__T_MST_URI_TYPE__MURIT_ID` FOREIGN KEY (`URI_TYPE`) REFERENCES `T_MST_URI_TYPE` (`MURIT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

