--
-- Table structure for table `T_CORE_USR`
--

DROP TABLE IF EXISTS `T_CORE_USR`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_USR` (
  `USR_UID` varchar(35) NOT NULL,
  `USR_ACCNID` varchar(35) NOT NULL,
  `USR_STATUS` char(1) NOT NULL,
  `USR_TYPE_ONLINE` varchar(1) NOT NULL,
  `USR_TYPE_MBOX` varchar(1) NOT NULL,
  `USR_NAME` varchar(35) DEFAULT NULL,
  `USR_PASS_NID` varchar(20) DEFAULT NULL,
  `USR_TITLE` varchar(35) DEFAULT NULL,
  `USR_DEPT` varchar(35) DEFAULT NULL,
  `USR_DT_REG` datetime NOT NULL,
  `USR_DT_COMM` datetime NOT NULL,
  `USR_DT_DEREG` datetime DEFAULT NULL,
  `USR_DT_REREG` datetime DEFAULT NULL,
  `USR_CLASS` varchar(35) DEFAULT NULL,
  `USR_ADDR1` varchar(64) DEFAULT NULL,
  `USR_ADDR2` varchar(64) DEFAULT NULL,
  `USR_ADDR3` varchar(64) DEFAULT NULL,
  `USR_PCODE` varchar(10) DEFAULT NULL,
  `USR_CITY` varchar(15) DEFAULT NULL,
  `USR_PROV` varchar(15) DEFAULT NULL,
  `USR_CTYCODE` varchar(3) DEFAULT NULL,
  `USR_TEL` varchar(1024) DEFAULT NULL,
  `USR_FAX` varchar(25) DEFAULT NULL,
  `USR_EMAIL` varchar(128) DEFAULT NULL,
  `USR_PWD` varchar(35) NOT NULL,
  `USR_PWD_1` varchar(35) DEFAULT NULL,
  `USR_PWD_2` varchar(35) DEFAULT NULL,
  `USR_PWD_3` varchar(35) DEFAULT NULL,
  `USR_PWD_4` varchar(35) DEFAULT NULL,
  `USR_DT_PWD_LUPD` datetime NOT NULL,
  `USR_PWD_VALIDTY` int DEFAULT NULL,
  `USR_PWD_FORCE` varchar(1) DEFAULT NULL,
  `USR_LOGIN_INVCNT` int NOT NULL,
  `USR_DT_LOGINOK` datetime DEFAULT NULL,
  `USR_DT_LOGINERR` datetime DEFAULT NULL,
  `USR_MBOX_ID` varchar(35) NOT NULL,
  `USR_MBOX_MAXCNT` int DEFAULT NULL,
  `USR_MBOX_MAXSIZ` int DEFAULT NULL,
  `USR_DUR_INBX` int DEFAULT NULL,
  `USR_DUR_ARCH` int DEFAULT NULL,
  `USR_DT_CREATE` datetime DEFAULT NULL,
  `USR_UID_CREATE` varchar(35) DEFAULT NULL,
  `USR_DT_LUPD` datetime DEFAULT NULL,
  `USR_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`USR_UID`),
  KEY `IDX_T_CORE_USR_1` (`USR_STATUS`),
  KEY `IDX_T_CORE_USR_2` (`USR_ACCNID`),
  KEY `IDX_T_CORE_USR_3` (`USR_DT_REG`),
  KEY `IDX_T_CORE_USR_4` (`USR_DT_COMM`),
  KEY `IDX_T_CORE_USR_5` (`USR_DT_DEREG`),
  KEY `IDX_T_CORE_USR_6` (`USR_DT_REREG`),
  KEY `FKY__T_CORE_USR__CTY_CODE_IDX` (`USR_CTYCODE`),
  KEY `FKY__T_CORE_USR__UCLA_CODE_IDX` (`USR_CLASS`),
  CONSTRAINT `FKY__T_CORE_USR__ACCN_ID` FOREIGN KEY (`USR_ACCNID`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FKY__T_CORE_USR__CTY_CODE` FOREIGN KEY (`USR_CTYCODE`) REFERENCES `T_MST_COUNTRY` (`CTY_CODE`),
  CONSTRAINT `FKY__T_CORE_USR__UCLA_CODE` FOREIGN KEY (`USR_CLASS`) REFERENCES `T_MST_UCLASS` (`UCLA_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

